class Temperatura {
  #celsius;

  constructor(celsius = 0) {
    this.celsius = celsius; // passa pelo setter, com validação
  }

  get celsius() {
    return this.#celsius;
  }

  set celsius(valor) {
    if (typeof valor !== "number" || Number.isNaN(valor)) {
      throw new TypeError("celsius tem de ser um número");
    }
    this.#celsius = valor;
  }

  get fahrenheit() {
    return (this.#celsius * 9) / 5 + 32;
  }

  set fahrenheit(valor) {
    this.celsius = ((valor - 32) * 5) / 9;
  }
}

const t = new Temperatura(20);
console.log(t.fahrenheit); // 68
t.fahrenheit = 100;
console.log(t.celsius.toFixed(2)); // "37.78"

const leitor = {
