class ContaBancaria {
  #saldo;
  #historico = [];

  constructor(saldoInicial = 0) {
    this.#saldo = saldoInicial;
  }

  depositar(valor) {
    if (valor <= 0) throw new RangeError("o valor tem de ser positivo");
    this.#saldo += valor;
    this.#historico.push({ tipo: "deposito", valor });
    return this.#saldo;
  }

  levantar(valor) {
    if (valor > this.#saldo) throw new Error("saldo insuficiente");
    this.#saldo -= valor;
    this.#historico.push({ tipo: "levantamento", valor });
    return this.#saldo;
  }

  get saldo() {
    return this.#saldo;
  }

  static eContaValida(obj) {
    return #saldo in obj; // verificação segura, sem lançar erro
  }
}

const conta = new ContaBancaria(100);
conta.depositar(50);
console.log(conta.saldo); // 150
console.log(ContaBancaria.eContaValida(conta)); // true
console.log(ContaBancaria.eContaValida({})); // false
// conta.#saldo fora da classe -> SyntaxError, nem chega a executar

class ValidadorEmail {
  #dominiosPermitidos;

  constructor(dominiosPermitidos = ["gmail.com", "outlook.com"]) {
    this.#dominiosPermitidos = dominiosPermitidos;
  }

  validar(email) {
    const normalizado = this.#normalizar(email);
    return this.#temFormatoValido(normalizado) && this.#dominioPermitido(normalizado);
  }

  #normalizar(email) {
    return email.trim().toLowerCase();
  }

  #temFormatoValido(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  #dominioPermitido(email) {
    const dominio = email.split("@")[1];
    return this.#dominiosPermitidos.includes(dominio);
  }
}

const validador = new ValidadorEmail();
console.log(validador.validar("  Ana@Gmail.com ")); // true
console.log(validador.validar("ana@empresa.pt")); // false

class ConfiguracaoApp {
  static #ambiente;
  static #limites;

  static {
    const modo = typeof process !== "undefined" ? process.env.NODE_ENV : "producao";
    this.#ambiente = modo === "desenvolvimento" ? "dev" : "prod";
  }

  static {
    this.#limites = { maxPedidos: this.#ambiente === "dev" ? 1000 : 100 };
