class Retangulo {
  #largura;
  #altura;

  constructor(largura = 1, altura = 1) {
    this.largura = largura;
    this.altura = altura;
  }

  get largura() {
    return this.#largura;
  }

  set largura(valor) {
    if (typeof valor !== "number" || valor <= 0) {
      throw new RangeError("largura tem de ser um número positivo");
    }
    this.#largura = valor;
  }

  get altura() {
    return this.#altura;
  }

  set altura(valor) {
    if (typeof valor !== "number" || valor <= 0) {
      throw new RangeError("altura tem de ser um número positivo");
    }
    this.#altura = valor;
  }

  get area() {
    return this.largura * this.altura;
  }

  get perimetro() {
    return 2 * (this.largura + this.altura);
  }
}

const r = new Retangulo(4, 5);
console.log(r.area); // 20
console.log(r.perimetro); // 18

try {
  r.largura = -2;
} catch (erro) {
  console.log(erro.message); // "largura tem de ser um número positivo"
}

class Produto {
  moeda = "EUR";
  #precoBase;
  #desconto = 0;

  constructor(nome, precoBase) {
    this.nome = nome;
    this.#precoBase = precoBase;
  }

  get desconto() {
    return this.#desconto;
  }

  set desconto(valor) {
    if (typeof valor !== "number" || valor < 0 || valor > 1) {
      throw new RangeError("desconto tem de estar entre 0 e 1");
    }
    this.#desconto = valor;
  }

  get precoFinal() {
    const preco = this.#precoBase * (1 - this.#desconto);
    return Number(preco.toFixed(2));
  }

  get etiqueta() {
    return `${this.nome}: ${this.precoFinal.toFixed(2)} ${this.moeda}`;
  }
}

const teclado = new Produto("Teclado", 50);
teclado.desconto = 0.1;
console.log(teclado.precoFinal); // 45
console.log(teclado.etiqueta); // "Teclado: 45.00 EUR"

class FilaDeTarefas {
  #tarefas = [];
  #proximoId = 1;

  adicionar(descricao) {
    const descricaoValida = this.#validarDescricao(descricao);
    const tarefa = { id: this.#proximoId++, descricao: descricaoValida };
    this.#tarefas.push(tarefa);
    return tarefa.id;
  }

  concluir(id) {
    const indice = this.#encontrarIndice(id);
    if (indice === -1) {
      throw new Error(`não existe nenhuma tarefa com o id ${id}`);
    }
    this.#tarefas.splice(indice, 1);
  }

  get pendentes() {
    return [...this.#tarefas];
  }

  #validarDescricao(descricao) {
    if (typeof descricao !== "string" || descricao.trim() === "") {
      throw new TypeError("descrição tem de ser uma string não vazia");
    }
    return descricao.trim();
  }

  #encontrarIndice(id) {
    return this.#tarefas.findIndex((tarefa) => tarefa.id === id);
  }
}

const fila = new FilaDeTarefas();
const id1 = fila.adicionar("  Rever pull request  ");
fila.adicionar("Escrever testes");
console.log(fila.pendentes.length); // 2
fila.concluir(id1);
console.log(fila.pendentes.length); // 1

class Sessao {
  static #totalCriadas;
  static #limiteMaximo;

  static {
    this.#totalCriadas = 0;
  }

  static {
    this.#limiteMaximo = 3;
  }

  id;

  constructor() {
    this.id = Sessao.#incrementar();
  }

  static #incrementar() {
    if (this.#totalCriadas >= this.#limiteMaximo) {
      throw new Error(`limite de ${this.#limiteMaximo} sessões ativas atingido`);
    }
    this.#totalCriadas += 1;
    return this.#totalCriadas;
  }

  static get total() {
    return this.#totalCriadas;
  }
}

const s1 = new Sessao();
const s2 = new Sessao();
const s3 = new Sessao();
console.log(s1.id, s2.id, s3.id); // 1 2 3
console.log(Sessao.total); // 3

try {
  new Sessao();
} catch (erro) {
  console.log(erro.message); // "limite de 3 sessões ativas atingido"
}
